      addEdge('qingxiao-basic-1', cleanSword.id, 'buff');
      addEdge('qingxiao-basic-2', cleanSword.id, 'buff');
      addEdge('qingxiao-basic-3', cleanSword.id, 'buff');
      addEdge('qingxiao-aerial-basic-1', cleanSword.id, 'buff');
      addEdge('qingxiao-aerial-basic-2', cleanSword.id, 'buff');
      addEdge('qingxiao-aerial-basic-3', cleanSword.id, 'buff');
      addEdge('qingxiao-immortal-basic', cleanSword.id, 'buff');
