      addChainChange('qingxiao-heavy', 2, P('重击·弦剑伤害倍率提升40%；天心空明强化时心识锁定附加层数提升至6层', 'Heavy Attack: Stringblade multiplier increases by 40%; Clear Heart enhancement applies 6 Mindmark Lock stacks'));
      addChainChange('qingxiao-consciousness', 2, P('心识锁定层数上限提升至25；重击·弦剑附加层数提升至6层', 'Mindmark Lock cap increases to 25; Heavy Attack: Stringblade applies 6 stacks'));
      addChainChange('qingxiao-condensed-consciousness', 2, P('凝识层数上限提升至25', 'Consciousness cap increases to 25'));
