        n('aemeath-shared-switch', uiText('构型切换', 'Configuration Shift'), 'other', uiText('按切换键', 'Press the switch input'), { formId: 'shared', effects: [uiText('切换另一形态并接入普攻', 'Switch to the other form and enter its Basic Attack chain')] }),
        n('aemeath-shared-outro', uiText('不可见的守候', 'Unseen Watch'), 'other', uiText('切换至下一位登场角色', 'Switch to the next character'), { formId: 'shared', effects: [uiText('造成热熔伤害并提供效果', 'Deal Fusion damage and provide an effect')] }),
        n('aemeath-shared-synchrony', uiText('同步率', 'Synchrony'), 'buff', uiText('施放动作积累', 'Built by actions'), { formId: 'shared', effects: [uiText('达到阈值后解锁光翼共奏', 'Unlock Winged Duet at the threshold')] })
